        let hits = 0, gates = 0, gatesTotal = 0, jumpsOk = 0, running = true, rafId = null, last = null, flash = 0, msg = '', msgUntil = 0;
        let airborneUntil = 0, tumbleUntil = 0, offSnow = 0;
