                const cand = [];
                for (let y = 1; y < ROWS - 1; y++) for (let x = 1; x < COLS - 1; x++) if (map[y][x] === '.') cand.push({ x, y });
                gTarget = cand[Math.floor(Math.random() * cand.length)];
