          list.push({ x: exit.x + 0.5, y: exit.y + 0.5, emoji: '🚪', scale: 0.85, lift: 0.02, glow: hasKey ? 'rgba(120,255,160,.9)' : undefined });
          const flicker = 0.75 + Math.sin(now / 90) * 0.15;
