          timerEl.textContent = 'のこり: ' + Math.ceil(rem / 1000) + 's';
          if (rem <= 0) { finish('timeout'); return; }
          const danger = hasKey && ghostDist < 3.5;
          if (danger) nearMs += dt * 1000;
