            const pulse = danger ? 0.35 + 0.3 * Math.abs(Math.sin(now / 160)) : 0;
            view.render(map, px, py, ang, sprites(now), { vignette: danger ? `rgba(120,0,25,${0.55 + pulse})` : undefined });
            ctx.restore();
            const ghostSeen = ghostDist < 4;
