    ctx.fillStyle = '#ff5a4a'; mgRoundRect(ctx, -w * 0.42, -h * 0.66, w * 0.16, h * 0.13, w * 0.02); mgRoundRect(ctx, w * 0.26, -h * 0.66, w * 0.16, h * 0.13, w * 0.02);
