          if (win) { score = clamp(62 + remRatio * 34 - hits * 5 - Math.min(12, offroadTime * 2), 55, 100); say('🏁 ゴール! ' + (hits === 0 ? 'ノーミス!' : 'しょうとつ ' + hits + 'かい')); }
          else { score = clamp(14 + progress * 44, 14, 58); say('タイムアップ… ' + Math.round(progress * 100) + '% まで はしった'); }
