          const score = clamp(Math.round(50 + (chips - START) * 0.5), 15, 100);
          say(chips > START ? `🏆 🪙${chips}で おわり! +${chips - START}` : chips === START ? 'イーブンで おわり' : `🪙${chips}で おわり… ${chips - START}`, 2600); render(performance.now());
