          if (now < msgUntil) { ctx.font = 'bold 14px sans-serif'; ctx.fillStyle = 'rgba(0,0,0,.6)'; ctx.fillRect(W / 2 - 90, 8, 180, 26); ctx.fillStyle = '#fff'; ctx.fillText(msg, W / 2, 21); }
